import { computeCandidates, countSolutions, isValidPlacement } from './sudoku.js';
import { TECHNIQUES, applyStep, findStep } from './techniques.js';
import { BANDS } from './score.js';

export function bandOf(score) {
  return BANDS.find(({ max }) => score <= max)?.name ?? 'Expert';
}

const BY_ID = new Map(TECHNIQUES.map((technique) => [technique.id, technique]));

// Generated by scripts/calibrate.mjs from 512 independently dug boards per band.
const PERCENTILES = {
  Medium: [
    [194, 0], [197, 0.015], [203, 0.04], [212, 0.08],
    [230, 0.15], [248, 0.25], [274.1, 0.35], [296, 0.45],
    [320, 0.55], [347, 0.65], [390.5, 0.75], [459.7, 0.85],
    [530.24, 0.92], [575.8, 0.96], [631.34, 0.985], [691.455, 0.995],
    [754, 1],
  ],
  Hard: [
    [967, 0], [1026.66, 0.015], [1073.76, 0.04], [1114.76, 0.08],
    [1144.65, 0.15], [1181.75, 0.25], [1209.7, 0.35], [1235.95, 0.45],
    [1271.05, 0.55], [1295.3, 0.65], [1332, 0.75], [1395.7, 0.85],
    [1473.96, 0.92], [1607.04, 0.96], [1836.685, 0.985], [1977.69, 0.995],
    [2170, 1],
  ],
  Expert: [
    [1523, 0], [1638.665, 0.015], [1683.2, 0.04], [1728.88, 0.08],
    [1788, 0.15], [1885, 0.25], [1992.85, 0.35], [2097.95, 0.45],
    [2323.1, 0.55], [2546.9, 0.65], [2829, 0.75], [3187.75, 0.85],
    [3583.72, 0.92], [3981.72, 0.96], [4468.13, 0.985], [4999.795, 0.995],
    [5247, 1],
  ],
};

export function rawDifficulty({ band, hardest, counts }, clues) {
  const weight = BY_ID.get(hardest)?.weight ?? 1;
  const locked = (counts.pointing ?? 0) + (counts.claiming ?? 0);
  const base = 6 * (81 - clues) + 3 * (counts['naked-single'] ?? 0) + 11 * (counts['hidden-single'] ?? 0) + 25 * locked;
  if (band === 'Medium') return base + 14 * (weight - 1);

  let hardSteps = 0;
  let expertSteps = 0;
  for (const [id, count] of Object.entries(counts)) {
    const technique = BY_ID.get(id);
    if (technique.tier >= 5) expertSteps += technique.weight * count;
    else if (technique.tier >= 3) hardSteps += technique.weight * count;
  }
  if (band === 'Hard') return base + 36 * weight + 5 * hardSteps;
  return base + 24 * weight + 3 * hardSteps + 5 * expertSteps;
}

function percentileAt(table, raw) {
  if (raw <= table[0][0]) return 0;
  for (let index = 1; index < table.length; index++) {
    const [upper, upperPercentile] = table[index];
    if (raw <= upper) {
      const [lower, lowerPercentile] = table[index - 1];
      return lowerPercentile + (upperPercentile - lowerPercentile) * (raw - lower) / (upper - lower);
    }
  }
  return 1;
}

export function ratePuzzle(givens, { maxTier = 6 } = {}) {
  const counts = {};
  let steps = 0;
  let hardest = null;
  if (givens.length !== 81) return { solvable: false, score: 0, band: 'Medium', hardest, steps, counts };

  let clues = 0;
  for (let cell = 0; cell < 81; cell++) {
    if (givens[cell] === 0) continue;
    if (!isValidPlacement(givens, cell, givens[cell])) {
      return { solvable: false, score: 0, band: 'Medium', hardest, steps, counts };
    }
    clues++;
  }

  let grid = givens.slice();
  let candidates = computeCandidates(grid);
  let unique;
  while (grid.includes(0)) {
    let step = findStep(grid, candidates, { maxTier, assumeUnique: unique !== false });
    if (step?.technique === 'unique-rectangle-type-1' && unique === undefined) {
      unique = countSolutions(givens) === 1;
      if (!unique) step = findStep(grid, candidates, { maxTier, assumeUnique: false });
    }
    if (!step) break;

    const technique = BY_ID.get(step.technique);
    if (!hardest || technique.weight > hardest.weight) hardest = technique;
    counts[technique.id] = (counts[technique.id] ?? 0) + 1;
    steps++;
    ({ grid, candidates } = applyStep(grid, candidates, step));
  }

  const tier = hardest?.tier ?? 1;
  const band = BANDS[Math.floor((tier - 1) / 2)];
  const rating = { solvable: !grid.includes(0), score: band.min, band: band.name, hardest: hardest?.id ?? null, steps, counts };
  const percentile = percentileAt(PERCENTILES[band.name], rawDifficulty(rating, clues));
  rating.score += Math.round(percentile * (band.max - band.min));
  return rating;
}
